export class DashboardDurableObject {
  constructor(state, env) { this.state = state; this.sessions = new Set(); }
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/ws") {
      if (request.headers.get("Upgrade") !== "websocket") return new Response("Expected WebSocket", { status: 426 });
      const pair = new WebSocketPair(); const client = pair[0]; const server = pair[1];
      server.accept(); this.sessions.add(server);
      server.send(JSON.stringify({ type: "init", data: await this.getData() }));
      server.addEventListener("message", async event => { try { const msg = JSON.parse(event.data); if (msg.type === "update") { await this.state.storage.put("dashboardData", msg.data); this.broadcast({ type: "update", data: msg.data }, server); } } catch (err) { server.send(JSON.stringify({ type: "error", message: String(err) })); } });
      server.addEventListener("close", () => this.sessions.delete(server)); server.addEventListener("error", () => this.sessions.delete(server));
      return new Response(null, { status: 101, webSocket: client });
    }
    if (url.pathname === "/api/data") { if (request.method === "GET") return Response.json(await this.getData()); if (request.method === "POST") { const body=await request.json(); await this.state.storage.put("dashboardData", body); this.broadcast({type:"update",data:body}); return Response.json({ok:true}); } }
    return new Response("Not found", { status: 404 });
  }
  async getData() {
    const def={appVersion:"7.0.0",companyName:"บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด",currentDepartmentId:"bcc2-insulation-packing",departments:[{id:"bcc2-insulation-packing",name:"ฝ่ายหุ้มฉนวนและบรรจุสาย BCC2",targetDays:"2937",monthRecords:{},data:{}}]};
    const saved=await this.state.storage.get("dashboardData");
    if(!saved)return def;
    if(!Array.isArray(saved.departments))return {...def,departments:[{id:"default-department",name:saved.departmentName||"ฝ่ายเริ่มต้น",targetDays:saved.targetDays||"2937",monthRecords:{},data:{}}],currentDepartmentId:"default-department"};
    return {...def,...saved};
  }
  broadcast(message, exceptSocket=null) { const payload=JSON.stringify(message); for(const s of this.sessions){ if(s!==exceptSocket){ try{s.send(payload)}catch{this.sessions.delete(s)} } } }
}
